"""Build the real-application .robot files from data/testcases_submit.csv.

Run:  python tools/csv_to_robot_submit.py [path/to/testcases_submit.csv]

* The CSV is the source of truth for ID, description, expected result and type. STEPS maps each ID to its keywords.
* Writes tests/submit/*.robot (the other test folders are not touched).
* 01_submit sends ONE REAL application and SKIPS unless JOBS_ALLOW_SUBMIT=yes. 02_after_submit only reads the CMS.
* Do not hand-edit the generated files; edit STEPS or resources/pages/submit.resource instead.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from csv_to_robot import read_cases, render_test  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
DEFAULT_CSV = ROOT / "data" / "testcases_submit.csv"
OUT_DIR = ROOT / "tests" / "submit"
PREFIX = "SB"

# group -> (file, title, suite setup, tags)
GROUPS = {
    "send": ("01_submit", "Send ONE real application and check the success window (opt-in)",
             "Send The Application", "automate    submit    real-submit"),
    "check": ("02_after_submit", "Look at the new application in the CMS (read only)",
              "Open Submit Check Browser", "automate    submit    needs-account"),
}
MANUAL_FILE = "99_manual"

# SB id -> (group, [steps])
STEPS = {
    "SB001": ("send", ["Success Page Should Contain    ${SUCCESS_TITLE}", "Location Should Contain    /apply"]),
    "SB002": ("send", ["Success Message Should Name The Job"]),
    "SB003": ("send", ["Success Message Should Say What Happens Next"]),
    "SB004": ("send", ["Success Message Should Name The Email"]),
    "SB005": ("send", ["Success Contact Line Should Work"]),
    "SB006": ("send", ["Success Buttons Should Be There"]),
    "SB007": ("send", ["Review Window Should Be Gone"]),
    "SB008": ("send", ["Back To Career Should Open The Home Page"]),
    "SB010": ("check", ["New Application Should Be On Top Of The Dashboard"]),
    "SB011": ("check", ["New Application Row Should Be Right"]),
    "SB012": ("check", ["New Application Date Should Not Be In The Future"]),
    "SB013": ("check", ["New Application Data Should Match What Was Typed"]),
    "SB014": ("check", ["New Application Consent Should Be Recorded"]),
    "SB015": ("check", ["New Application Files Should Be Right"]),
    "SB016": ("check", ["New Application HR Status Should Be Valid"]),
    "SB017": ("check", ["New Application AI Result Should Be Known"]),
    "SB018": ("check", ["Confirmation Email Should Be Logged"]),
    "SB019": ("check", ["Confirmation Email Time Should Follow The Application"]),
    "SB020": ("check", ["Head Draft Should Know The New Application"]),
    "SB021": ("check", ["New Application History Should Follow The Rule"]),
    "SB022": ("check", ["Dashboard Badge Should Match The History"]),
}

# Behaviour read from the dev site (or an expectation of mine) that the team must confirm.
ASSUMPTION_IDS = {"SB003", "SB007", "SB012", "SB019", "SB021", "SB022"}


def file_header(title, ids, setup=None, tags=None, manual=False):
    out = ["*** Settings ***",
           f"Documentation     {title} ({ids[0]} to {ids[-1]}). GENERATED by tools/csv_to_robot_submit.py - do not edit."]
    if manual:
        out += ["Test Tags         manual"]
    else:
        out += ["Resource          ../../resources/all_pages.resource",
                f"Suite Setup       {setup}",
                "Suite Teardown    Close All Browsers",
                f"Test Tags         {tags}"]
    return "\n".join(out) + "\n\n\n*** Test Cases ***\n"


def main():
    csv_path = Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_CSV
    cases = read_cases(csv_path, PREFIX)
    auto = [c for c in cases if c["type"] == "automate"]
    manual = [c for c in cases if c["type"] == "manual"]

    missing = [c["id"] for c in auto if c["id"] not in STEPS]
    extra = [i for i in STEPS if i not in {c["id"] for c in auto}]
    if missing or extra:
        sys.exit(f"STEPS mismatch. In CSV as automate but no steps: {missing}. Steps but not automate in CSV: {extra}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for old in OUT_DIR.glob("*.robot"):
        old.unlink()

    by_group = {g: [] for g in GROUPS}
    for case in auto:
        group, steps = STEPS[case["id"]]
        tags = [case["id"], group]
        if case["id"] in ASSUMPTION_IDS:
            tags.append("assumption")
        by_group[group].append(render_test(case, steps, tags))

    for group, (filename, title, setup, tags) in GROUPS.items():
        tests = by_group[group]
        ids = [t.split()[0] for t in tests]
        body = file_header(title, ids, setup, tags) + "\n\n".join(tests) + "\n"
        (OUT_DIR / f"{filename}.robot").write_text(body, encoding="utf-8", newline="\n")

    manual_tests = [
        render_test(c, ["Skip    Manual case: run by hand and record the result in the CSV"], [c["id"], "manual"])
        for c in manual
    ]
    ids = [c["id"] for c in manual]
    body = file_header("Manual cases (always skipped)", ids, manual=True) + "\n\n".join(manual_tests) + "\n"
    (OUT_DIR / f"{MANUAL_FILE}.robot").write_text(body, encoding="utf-8", newline="\n")

    print(f"automate: {len(auto)}  manual: {len(manual)}  total: {len(cases)}")
    for group, (filename, *_rest) in GROUPS.items():
        print(f"  submit/{filename}.robot  {len(by_group[group])}")
    print(f"  submit/{MANUAL_FILE}.robot  {len(manual)}")


if __name__ == "__main__":
    main()
